export function getBlobShapeStyle(blob?: { shape?: BlobShape; pill?: boolean } | null) {
  if (!blob) {
    return {
      borderRadius: "50%",
      clipPath: undefined,
      svgPath: undefined,
      shapeId: "circle" as BlobShape,
      label: "Circle",
    };
  }

  const shapeId: BlobShape = blob.shape ?? (blob.pill ? "pill" : "circle");
  const shape = BLOB_SHAPES.find((s) => s.id === shapeId) || BLOB_SHAPES[0];

  return {
    borderRadius: shape.borderRadius,
    clipPath: shape.clipPath,
    svgPath: shape.svgPath,
    shapeId,
    label: shape.label,
  };
}

export const hexToRgba = (hex: string, alpha: number): string => {
  if (!hex || typeof hex !== "string") return `rgba(0, 0, 0, ${alpha})`;
  let cleanHex = hex.replace("#", "");

  if (cleanHex.length === 3) {
    cleanHex = cleanHex
      .split("")
      .map((c) => c + c)
      .join("");
  }

  if (cleanHex.length !== 6) {
    return hex; // fallback dacă este deja rgb sau alt format
  }

  const num = parseInt(cleanHex, 16);
  const r = (num >> 16) & 255;
  const g = (num >> 8) & 255;
  const b = num & 255;

  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
};

